mod bootstrap;
mod commands;
mod config;
mod driver;
mod render;
mod repl;

use std::path::PathBuf;

use anyhow::Result;
use clap::{Parser, Subcommand};
use niuse_core::Store;

#[derive(Parser, Debug)]
#[command(
    name = "niuse",
    version,
    about = "A personal engineering companion built on niucode"
)]
struct Cli {
    /// Provider preset (deepseek or openai)
    #[arg(long, global = true, default_value = "deepseek")]
    preset: String,
    /// Override the preset model
    #[arg(long, global = true)]
    model: Option<String>,
    /// Disable DeepSeek thinking mode
    #[arg(long, global = true)]
    no_thinking: bool,
    /// Working directory (defaults to cwd); `/cd` changes it at runtime
    #[arg(long, global = true)]
    cwd: Option<PathBuf>,
    /// Sandbox: read-only, workspace-write, or full-access
    #[arg(long, global = true, default_value = "workspace-write")]
    sandbox: String,
    /// Approval: ask, on-failure, or never
    #[arg(long, global = true, default_value = "on-failure")]
    approval: String,
    /// Network: on or off
    #[arg(long, global = true, default_value = "off")]
    network: String,
    /// Override the niuse home (defaults to $NIUSE_HOME or ~/.niuse)
    #[arg(long, global = true)]
    home: Option<PathBuf>,
    /// Maximum model turns per user request (0 = no hard cap)
    #[arg(long, global = true, default_value_t = 0)]
    max_steps: usize,
    #[command(subcommand)]
    command: Option<Command>,
}

#[derive(Subcommand, Debug, Clone)]
enum Command {
    /// Run one prompt through the agent, then exit
    Exec { prompt: String },
    /// Inspect and edit durable memory
    Mem {
        #[command(subcommand)]
        command: MemCommand,
    },
    /// Inspect and close open loops
    Loops {
        #[command(subcommand)]
        command: LoopsCommand,
    },
    /// Show the journal
    Journal {
        #[arg(long, default_value_t = 7)]
        days: usize,
    },
    /// Create or show identity.md
    Identity {
        #[command(subcommand)]
        command: IdentityCommand,
    },
    /// Mine recent niucode sessions for memory candidates
    Bootstrap {
        /// Maximum number of sessions to scan
        #[arg(long, default_value_t = 40)]
        limit: usize,
        /// Only sessions modified within this many days
        #[arg(long, default_value_t = 90)]
        since_days: i64,
    },
    /// Review bootstrapped candidates
    Review,
    /// Show store and prompt status
    Status,
}

#[derive(Subcommand, Debug, Clone)]
enum MemCommand {
    /// List memories
    List {
        /// Include expired entries
        #[arg(long)]
        all: bool,
    },
    /// Add a memory directly
    Add {
        text: String,
        /// preference or lesson
        #[arg(long, default_value = "preference")]
        kind: String,
        #[arg(long, value_delimiter = ',')]
        tags: Vec<String>,
        /// Store even if the secret scan matches
        #[arg(long)]
        force: bool,
    },
    /// Delete a memory
    Forget { id: String },
    /// Refresh the confirmation date
    Confirm { id: String },
    /// Review stale memories interactively
    Review,
}

#[derive(Subcommand, Debug, Clone)]
enum LoopsCommand {
    /// List loops
    List {
        /// Include closed loops
        #[arg(long)]
        all: bool,
    },
    /// Close a loop
    Done { id: String },
}

#[derive(Subcommand, Debug, Clone)]
enum IdentityCommand {
    /// Answer eight questions and write identity.md
    Init {
        /// Overwrite an existing identity.md
        #[arg(long)]
        force: bool,
    },
    /// Print identity.md
    Show,
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();
    let store = match &cli.home {
        Some(path) => Store::at(path.clone()),
        None => Store::discover()?,
    };
    store.init()?;
    let command = cli.command.clone();

    match command {
        None => {
            let app = repl::App::new(&cli, store)?;
            app.run().await
        }
        Some(Command::Exec { prompt }) => {
            let app = repl::App::new(&cli, store)?;
            repl::run_exec(app, prompt).await
        }
        Some(Command::Mem { command }) => match command {
            MemCommand::List { all } => commands::mem_list(&store, all),
            MemCommand::Add {
                text,
                kind,
                tags,
                force,
            } => commands::mem_add(&store, &text, &kind, tags, force),
            MemCommand::Forget { id } => commands::mem_forget(&store, &id),
            MemCommand::Confirm { id } => commands::mem_confirm(&store, &id),
            MemCommand::Review => commands::mem_review(&store),
        },
        Some(Command::Loops { command }) => match command {
            LoopsCommand::List { all } => commands::loops_list(&store, all),
            LoopsCommand::Done { id } => commands::loops_done(&store, &id),
        },
        Some(Command::Journal { days }) => commands::journal_show(&store, days),
        Some(Command::Identity { command }) => match command {
            IdentityCommand::Init { force } => commands::identity_init(&store, force),
            IdentityCommand::Show => commands::identity_show(&store),
        },
        Some(Command::Bootstrap { limit, since_days }) => {
            let app = repl::App::new(&cli, store)?;
            bootstrap::run(
                &app.store,
                app.provider.as_ref(),
                &app.model,
                limit,
                since_days,
            )
            .await
        }
        Some(Command::Review) => bootstrap::review(&store),
        Some(Command::Status) => commands::status(&store),
    }
}

//! Store-only commands. None of these construct a provider, so they work
//! offline and without credentials.

use anyhow::{bail, Context, Result};
use niuse_core::model::one_line;
use niuse_core::policy::secret_reason;
use niuse_core::prompt::compose;
use niuse_core::{Date, MemoryEntry, MemoryKind, Store};
use std::io::{self, Write};

pub fn mem_list(store: &Store, all: bool) -> Result<()> {
    let today = Date::today();
    let memories = store.memories()?;
    let shown: Vec<&MemoryEntry> = memories
        .iter()
        .filter(|entry| all || !entry.is_expired(today))
        .collect();

    let stale = memories
        .iter()
        .filter(|entry| entry.is_stale(today) && !entry.is_expired(today))
        .count();
    let expired = memories
        .iter()
        .filter(|entry| entry.is_expired(today))
        .count();
    println!(
        "{} 条记忆 · {} 条待验证 · {} 条已过期（不再自动注入）",
        memories.len(),
        stale,
        expired
    );
    if shown.is_empty() {
        println!("（空。用 `niuse mem add \"...\"` 或等待对话中的候选。）");
        return Ok(());
    }
    for entry in shown {
        let age = entry.age_days(today);
        let age_label = match age {
            0 => "今天".to_string(),
            1..=30 => format!("{age} 天前"),
            _ if entry.is_expired(today) => format!("{age} 天前 · 已过期"),
            _ => format!("{age} 天前 · 待验证"),
        };
        let tags = if entry.tags.is_empty() {
            String::new()
        } else {
            format!(" [{}]", entry.tags.join(", "))
        };
        println!(
            "m-{}  {}{}  {}  {}",
            entry.id,
            entry.kind.as_str(),
            tags,
            age_label,
            entry.text
        );
    }
    Ok(())
}

pub fn mem_add(
    store: &Store,
    text: &str,
    kind: &str,
    tags: Vec<String>,
    force: bool,
) -> Result<()> {
    let kind = MemoryKind::parse(kind)
        .with_context(|| format!("unknown kind {kind:?}; use preference or lesson"))?;
    let text = one_line(text.trim().to_string());
    if text.is_empty() {
        bail!("memory text is empty");
    }
    if let Some(reason) = secret_reason(&text) {
        if !force {
            bail!("refusing to store: looks like a {reason}; pass --force to override");
        }
        eprintln!("warning: overriding secret scan ({reason})");
    }
    let entry = store.add_memory(MemoryEntry::new(kind, text, tags, Date::today(), None))?;
    println!("m-{}", entry.id);
    Ok(())
}

pub fn mem_forget(store: &Store, id: &str) -> Result<()> {
    let id = normalize_id(id);
    if store.remove_memory(&id)? {
        println!("forgot m-{id}");
    } else {
        bail!("no memory m-{id}");
    }
    Ok(())
}

pub fn mem_confirm(store: &Store, id: &str) -> Result<()> {
    let id = normalize_id(id);
    let updated = store.update_memory(&id, |entry| entry.confirmed = Date::today())?;
    match updated {
        Some(entry) => println!("m-{} confirmed {}", entry.id, entry.confirmed),
        None => bail!("no memory m-{id}"),
    }
    Ok(())
}

pub fn mem_review(store: &Store) -> Result<()> {
    let today = Date::today();
    let stale: Vec<MemoryEntry> = store
        .memories()?
        .into_iter()
        .filter(|entry| entry.is_stale(today))
        .collect();
    if stale.is_empty() {
        println!("没有需要复核的记忆。");
        return Ok(());
    }

    for entry in stale {
        println!();
        println!(
            "m-{} · {} · 最后确认 {}（{} 天前）",
            entry.id,
            entry.kind.as_str(),
            entry.confirmed,
            entry.age_days(today)
        );
        println!("  {}", entry.text);
        print!("[y] 仍然成立  [d] 删除  [s] 跳过  [q] 退出 > ");
        let _ = io::stdout().flush();

        let mut line = String::new();
        if io::stdin().read_line(&mut line)? == 0 {
            break;
        }
        match line.trim().to_lowercase().as_str() {
            "y" | "yes" => {
                store.update_memory(&entry.id, |entry| entry.confirmed = today)?;
                println!("  已确认");
            }
            "d" | "delete" => {
                store.remove_memory(&entry.id)?;
                println!("  已删除");
            }
            "q" | "quit" => break,
            _ => println!("  跳过"),
        }
    }
    Ok(())
}

pub fn loops_list(store: &Store, all: bool) -> Result<()> {
    let today = Date::today();
    let loops = store.loops()?;
    let open = loops.iter().filter(|item| !item.done).count();
    println!("{} 条承诺 · {} 条未完成", loops.len(), open);
    for item in &loops {
        if item.done && !all {
            continue;
        }
        let mark = if item.done { "x" } else { " " };
        let due = match item.due {
            Some(due) if item.is_overdue(today) => format!("（截止 {due}，已逾期）"),
            Some(due) => format!("（截止 {due}）"),
            None => String::new(),
        };
        println!("[{mark}] l-{} {}{due}", item.id, item.text);
    }
    Ok(())
}

pub fn loops_done(store: &Store, id: &str) -> Result<()> {
    let id = normalize_id(id);
    if store.close_loop(&id)? {
        println!("closed l-{id}");
    } else {
        bail!("no loop l-{id}");
    }
    Ok(())
}

pub fn journal_show(store: &Store, days: usize) -> Result<()> {
    let days = store.recent_journal(days)?;
    if days.is_empty() {
        println!("（还没有 journal。）");
        return Ok(());
    }
    for day in days {
        println!("## {}", day.date);
        for bullet in &day.bullets {
            println!("- {bullet}");
        }
        println!();
    }
    Ok(())
}

