//! Runtime settings: provider construction and the three security axes.

use std::path::PathBuf;
use std::sync::Arc;

use anyhow::{bail, Context, Result};
use niucode_agent::ApprovalMode;
use niucode_auth::AuthStore;
use niucode_provider::{OpenAiConfig, OpenAiProvider, Preset, Provider, ThinkingMode};
use niucode_tools::{NetworkMode, SandboxMode, SandboxPolicy};

pub struct ProviderBundle {
    pub provider: Arc<dyn Provider>,
    pub provider_id: String,
    pub model: String,
}

pub fn build_provider(
    preset: &str,
    model: Option<&str>,
    no_thinking: bool,
) -> Result<ProviderBundle> {
    let preset = Preset::parse(preset).with_context(|| format!("unknown provider {preset:?}"))?;
    let auth = AuthStore::new().context("initialize auth store")?;
    let credential = auth.resolve(preset.as_str())?.with_context(|| {
        format!(
            "no credential for {}; run `niucode auth set {}` or set {}",
            preset.as_str(),
            preset.as_str(),
            preset.api_key_env()
        )
    })?;

    let provider_id = preset.as_str().to_string();
    let model = model
        .map(str::to_string)
        .unwrap_or_else(|| default_model(&preset));

    let mut config = OpenAiConfig::preset_config(preset)?;
    config.api_key = credential.key.expose().to_string();
    config.model = model.clone();
    if no_thinking && preset == Preset::DeepSeek {
        config.thinking = Some(ThinkingMode::Disabled);
    }
    let provider: Arc<dyn Provider> = Arc::new(OpenAiProvider::for_preset(preset, config)?);
    Ok(ProviderBundle {
        provider,
        provider_id,
        model,
    })
}

fn default_model(preset: &Preset) -> String {
    niucode_provider::find_provider(preset.as_str())
        .map(|descriptor| descriptor.default_model.to_string())
        .unwrap_or_else(|| preset.default_model().to_string())
}

pub fn parse_sandbox(value: &str) -> Result<SandboxMode> {
    match value {
        "read-only" => Ok(SandboxMode::ReadOnly),
        "workspace-write" => Ok(SandboxMode::WorkspaceWrite),
        "full-access" => Ok(SandboxMode::FullAccess),
        other => bail!("unknown sandbox {other:?}; use read-only, workspace-write, or full-access"),
    }
}

pub fn parse_network(value: &str) -> Result<NetworkMode> {
    match value {
        "on" => Ok(NetworkMode::On),
        "off" => Ok(NetworkMode::Off),
        other => bail!("unknown network {other:?}; use on or off"),
    }
}

pub fn parse_approval(value: &str) -> Result<ApprovalMode> {
    match value {
        "ask" => Ok(ApprovalMode::Ask),
        "on-failure" => Ok(ApprovalMode::OnFailure),
        "never" => Ok(ApprovalMode::Never),
        other => bail!("unknown approval {other:?}; use ask, on-failure, or never"),
    }
}

/// Mirror niucode's fallback: without bwrap, `never` is refused and the other
/// modes degrade to explicit per-action approval.
pub fn resolve_policy(
    sandbox: &str,
    approval: &str,
    network: &str,
) -> Result<(SandboxPolicy, ApprovalMode, bool)> {
    let mut approval = parse_approval(approval)?;
    let policy = SandboxPolicy::new(parse_sandbox(sandbox)?, parse_network(network)?);
    let mut allow_unsandboxed = false;

    if policy.backend() == "unavailable" {
        match approval {
            ApprovalMode::Never => bail!(
                "sandbox backend bwrap is unavailable; install bubblewrap or use --approval ask"
            ),
            ApprovalMode::OnFailure => {
                eprintln!(
                    "warning: sandbox backend unavailable; falling back to per-action approval"
                );
                approval = ApprovalMode::Ask;
                allow_unsandboxed = true;
            }
            ApprovalMode::Ask => {
                eprintln!("warning: sandbox backend unavailable; using per-action approval");
                allow_unsandboxed = true;
            }
        }
    }

    Ok((policy, approval, allow_unsandboxed))
}

pub fn resolve_cwd(cwd: Option<PathBuf>) -> Result<PathBuf> {
    let cwd = match cwd {
        Some(path) => path,
        None => std::env::current_dir().context("resolve current directory")?,
    };
    let cwd = cwd
        .canonicalize()
        .with_context(|| format!("resolve working directory {}", cwd.display()))?;
    if !cwd.is_dir() {
        bail!("working directory {} is not a directory", cwd.display());
    }
    Ok(cwd)
}

//! Interactive REPL and one-shot execution.

use std::fs;
use std::io::{self, Write};
use std::path::PathBuf;
use std::sync::Arc;

use anyhow::{bail, Context, Result};
use niucode_agent::ApprovalMode;
use niucode_core::load;
use niucode_provider::Provider;
use niucode_tools::SandboxPolicy;
use niuse_core::model::one_line;
use niuse_core::policy::{conflicts, secret_reason};
use niuse_core::prompt::compose;
use niuse_core::{Block, Date, LoopItem, MemoryEntry, MemoryKind, Store};

use crate::commands;
use crate::config::{build_provider, resolve_cwd, resolve_policy};
use crate::driver::{self, SessionMeta, Thread};
use crate::render::{self, Renderer};
use crate::Cli;

pub struct App {
    pub store: Store,
    pub provider: Arc<dyn Provider>,
    pub provider_id: String,
    pub model: String,
    pub policy: SandboxPolicy,
    pub approval: ApprovalMode,
    pub allow_unsandboxed: bool,
    pub cwd: PathBuf,
    pub max_steps: usize,
    pub prompt: String,
    pub prompt_tokens: usize,
    memory_enabled: bool,
    suppress_candidates: bool,
}

impl App {
    pub fn new(cli: &Cli, store: Store) -> Result<Self> {
        let bundle = build_provider(&cli.preset, cli.model.as_deref(), cli.no_thinking)?;
        let (policy, approval, allow_unsandboxed) =
            resolve_policy(&cli.sandbox, &cli.approval, &cli.network)?;
        let cwd = resolve_cwd(cli.cwd.clone())?;
        let memory_enabled = std::env::var("NIUSE_MEMORY")
            .map(|value| value.trim().to_lowercase() != "off")
            .unwrap_or(true);

        let mut app = Self {
            store,
            provider: bundle.provider,
            provider_id: bundle.provider_id,
            model: bundle.model,
            policy,
            approval,
            allow_unsandboxed,
            cwd,
            max_steps: cli.max_steps,
            prompt: String::new(),
            prompt_tokens: 0,
            memory_enabled,
            suppress_candidates: false,
        };
        app.rebuild_prompt()?;
        Ok(app)
    }

    pub fn rebuild_prompt(&mut self) -> Result<()> {
        let today = Date::today();
        let identity = self.store.identity()?;
        let user = self.store.user()?;
        let memories = if self.memory_enabled {
            self.store.memories()?
        } else {
            Vec::new()
        };
        let loops = self.store.loops()?;
        let journal = self.store.recent_journal(3)?;
        let composition = compose(
            identity.as_deref(),
            user.as_deref(),
            &memories,
            &loops,
            &journal,
            today,
        );
        self.prompt = composition.system;
        self.prompt_tokens = composition.tokens;
        Ok(())
    }

    pub async fn run(mut self) -> Result<()> {
        let path = self.store.session_path();
        let meta = SessionMeta {
            cwd: &self.cwd,
            model: &self.model,
            provider: &self.provider_id,
            policy: self.policy,
            approval: self.approval,
        };
        let mut thread = driver::open_thread(&path, &meta)?;
        let mut history = driver::history(&thread.path)?;
        self.banner();

        loop {
            print!("\n{}", self.prompt_label());
            let _ = io::stdout().flush();
            let Some(line) = render::read_line() else {
                println!();
                break;
            };
            let input = line.trim();
            if input.is_empty() {
                continue;
            }
            if input.starts_with('/') {
                if matches!(self.command(input, &thread)?, Flow::Quit) {
                    break;
                }
                continue;
            }

            let config = driver::agent_config(
                &self.provider_id,
                &self.model,
                &self.cwd,
                self.prompt.clone(),
                self.policy,
                self.approval,
                self.allow_unsandboxed,
                self.max_steps,
            );
            let mut renderer = Renderer::new();
            let result = driver::run_turn(
                self.provider.as_ref(),
                &mut thread.log,
                &config,
                input,
                history,
                &mut renderer,
            )
            .await;
            let parsed = renderer.finish();
            match result {
                Ok(Some(_)) => {
                    let source = thread.log.id().to_string();
                    self.handle_blocks(parsed.blocks, &source)?;
                }
                Ok(None) => println!("[cancelled]"),
                Err(error) => eprintln!("error: {error:#}"),
            }
            history = match driver::history(&thread.path) {
                Ok(history) => history,
                Err(error) => {
                    eprintln!("warning: cannot reload session history: {error:#}");
                    Vec::new()
                }
            };
        }

        driver::append_end(&thread.log)?;
        Ok(())
    }

    fn banner(&self) {
        let today = Date::today();
        let memories = self.store.memories().unwrap_or_default();
        let stale = memories
            .iter()
            .filter(|entry| entry.is_stale(today) && !entry.is_expired(today))
            .count();
        let open = self
            .store
            .loops()
            .unwrap_or_default()
            .iter()
            .filter(|item| !item.done)
            .count();

        println!(
            "niuse · {} · {} / {}",
            self.model,
            self.policy.mode.as_str(),
            self.approval.as_str()
        );
        println!(
            "{} 条记忆（{} 条待验证）· {} 条未完成承诺 · prompt ~{} tokens",
            memories.len(),
            stale,
            open,
            self.prompt_tokens
        );
        println!("/help 查看命令 · Ctrl-C 取消当前 turn · Ctrl-D 退出");
        if !self.memory_enabled {
            println!("NIUSE_MEMORY=off：本次 session 不注入记忆，也不提议新记忆。");
        }
        if self.store.identity().unwrap_or(None).is_none() {
            println!("提示：还没有 identity.md，运行 `niuse identity init` 定义它是谁。");
        }

//! Minimal terminal rendering for `niuse`. The niucode TUI lives behind a
//! binary-only crate, so niuse owns this small renderer and keeps the turn loop
//! as the single source of events.

use std::io::{self, Write};

use niucode_agent::{AgentEvent, ApprovalRequest};
use niuse_core::{parse, Parsed, StreamFilter};

pub struct Renderer {
    filter: StreamFilter,
    at_line_start: bool,
}

impl Renderer {
    pub fn new() -> Self {
        Self {
            filter: StreamFilter::new(),
            at_line_start: true,
        }
    }

    pub fn event(&mut self, event: AgentEvent) {
        match event {
            AgentEvent::TextDelta(delta) => {
                let visible = self.filter.push(&delta);
                if !visible.is_empty() {
                    print!("{visible}");
                    let _ = io::stdout().flush();
                    self.at_line_start = visible.ends_with('\n');
                }
            }
            AgentEvent::ReasoningDelta(_) => {}
            AgentEvent::ToolCall { name, input } => {
                self.newline();
                println!("→ {} {}", name, truncate(&input.to_string(), 180));
                self.at_line_start = true;
            }
            AgentEvent::ToolResult {
                name, ok, summary, ..
            } => {
                self.newline();
                let mark = if ok { "✓" } else { "✗" };
                println!("{mark} {name}: {}", truncate(&summary, 240));
                self.at_line_start = true;
            }
            AgentEvent::Warning(warning) => {
                self.newline();
                println!("! {warning}");
                self.at_line_start = true;
            }
            AgentEvent::Compaction {
                before_tokens,
                after_tokens,
                ..
            } => {
                self.newline();
                println!("[compacted {before_tokens} → {after_tokens} tokens]");
                self.at_line_start = true;
            }
            AgentEvent::TurnEnd { .. } | AgentEvent::Phase(_) => {}
        }
    }

    /// Flush held text, print a final newline, and return the parsed answer.
    pub fn finish(&mut self) -> Parsed {
        let (tail, raw) = self.filter.finish();
        if !tail.is_empty() {
            print!("{tail}");
            let _ = io::stdout().flush();
            self.at_line_start = tail.ends_with('\n');
        }
        self.newline();
        parse(&raw)
    }

    fn newline(&mut self) {
        if !self.at_line_start {
            println!();
            let _ = io::stdout().flush();
            self.at_line_start = true;
        }
    }
}

impl Default for Renderer {
    fn default() -> Self {
        Self::new()
    }
}

/// Per-action approval for mutating tools. Reads one line from the terminal.
pub fn approve(request: &ApprovalRequest) -> bool {
    println!();
    println!("[approval] {}: {}", request.tool, request.summary);
    if let Some(preview) = &request.preview {
        if preview.added + preview.removed > 0 {
            println!("  +{} −{}", preview.added, preview.removed);
        }
        if let Some(warning) = &preview.warning {
            println!("  warning: {warning}");
        }
    }
    print!("allow? [y/N] ");
    let _ = io::stdout().flush();

    let mut line = String::new();
    if io::stdin().read_line(&mut line).is_err() {
        return false;
    }
    matches!(line.trim().to_lowercase().as_str(), "y" | "yes")
}

/// Read one line from stdin; `None` on EOF.
pub fn read_line() -> Option<String> {
    let mut line = String::new();
    match io::stdin().read_line(&mut line) {
        Ok(0) => None,
        Ok(_) => Some(line.trim_end().to_string()),
        Err(_) => None,
    }
}

fn truncate(text: &str, max_chars: usize) -> String {
    let mut out = String::new();
    for (count, character) in text.chars().enumerate() {
        if count >= max_chars {
            out.push('…');
            break;
        }
        if character == '\n' {
            out.push(' ');
        } else {
            out.push(character);
        }
    }
    out
}

//! System-prompt assembly.
//!
//! Stable sections come first (persona, identity, user, memory, protocol) so the
//! provider can reuse its prompt cache; volatile sections (today, loops,
//! journal) come last. The whole prompt is built once per session.

use crate::date::Date;
use crate::model::{JournalDay, LoopItem, MemoryEntry};

pub const IDENTITY_BUDGET: usize = 600;
pub const USER_BUDGET: usize = 600;
pub const MEMORY_BUDGET: usize = 2_000;
pub const LOOP_BUDGET: usize = 300;
pub const JOURNAL_BUDGET: usize = 600;

pub const BASE: &str = "你是 niuse，一个长期陪伴这位用户的工程伙伴。\n\
你不是通用助手。你的价值不在「什么都能答」，而在三件事：记得他做过的判断、追踪你自己许下的承诺、在他判断错的时候开口。\n\
工作方式：\n\
- 具体优于笼统。引用过去的决定时说清楚是哪一次、为什么，不要泛泛地说「你喜欢简洁」。\n\
- 不表演情绪，不用昵称轰炸，不主动抒情。\n\
- 不同意就直说，给出理由，对事不对人。\n\
- 不确定就去查；查不到就说不知道，不要补全。\n\
- 记忆是偏好，不是法律。与当前证据冲突时以证据为准，并指出你不同意哪一条。";

pub const PROTOCOL: &str = "## 记忆协议\n\
你可以在回答的最后输出以下块。niuse 会解析它们，并从用户看到的文本里剥离；不要在正文里提到这些块。\n\n\
<<niuse:memory kind=preference tags=rust,testing>>\n\
一句能独立看懂、跨项目仍然成立的结论\n\
<</niuse:memory>>\n\n\
<<niuse:loop due=2026-10-22>>\n\
你答应过、或用户交代你下次要做的事\n\
<</niuse:loop>>\n\n\
<<niuse:journal>>\n\
- 今天发生的决定、转折、未解问题或情绪变化（最多 3 条）\n\
<</niuse:journal>>\n\n\
规则：\n\
- 每轮最多一个 memory 块；没有值得记的就不要输出，连续多轮没有候选是正常的。\n\
- 只记「跨会话仍然有用、在仓库里 grep 不出来、一句话说得清」的内容。\n\
- memory 写偏好、决策、踩坑；不要写代码事实、环境配置、别人的信息。\n\
- 绝不把密钥、token、密码、客户名写进任何块。\n\
- journal 只写与上次不同的东西；「今天修了个 bug」这种流水账不要写。";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Composition {
    pub system: String,
    pub memory_injected: usize,
    pub memory_dropped: usize,
    pub tokens: usize,
}

/// Conservative token estimate: ASCII averages four characters per token,
/// every non-ASCII character counts as one. Matches niucode's estimator.
pub fn estimate_text_tokens(text: &str) -> usize {
    let mut ascii = 0usize;
    let mut other = 0usize;
    for character in text.chars() {
        if character.is_ascii() {
            ascii += 1;
        } else {
            other += 1;
        }
    }
    ascii.div_ceil(4) + other
}

pub fn compose(
    identity: Option<&str>,
    user: Option<&str>,
    memories: &[MemoryEntry],
    loops: &[LoopItem],
    journal: &[JournalDay],
    today: Date,
) -> Composition {
    let mut sections: Vec<(&str, String)> = Vec::new();

    if let Some(identity) = identity.map(str::trim).filter(|text| !text.is_empty()) {
        sections.push(("你是谁", truncate_to_tokens(identity, IDENTITY_BUDGET)));
    }
    if let Some(user) = user.map(str::trim).filter(|text| !text.is_empty()) {
        sections.push(("你在和谁一起工作", truncate_to_tokens(user, USER_BUDGET)));
    }

    let (memory_text, memory_injected, memory_dropped) = memory_section(memories, today);
    if !memory_text.is_empty() {
        sections.push((
            "长期记忆",
            format!(
                "以下是你和用户长期积累的判断。它们是偏好，不是法律；与当前证据冲突时以证据为准，并指出你不同意哪一条。\n\n{memory_text}"
            ),
        ));
    }

    // Constant: keeping it before the volatile sections lengthens the stable
    // cache prefix.
    sections.push(("记忆协议", PROTOCOL.to_string()));
    sections.push(("今天", today.format()));

    let loop_text = loop_section(loops, today);
    if !loop_text.is_empty() {
        sections.push(("未完成的承诺", loop_text));
    }

    let journal_text = journal_section(journal);
    if !journal_text.is_empty() {
        sections.push(("最近几天", journal_text));
    }

    let mut system = String::from(BASE);
    for (title, body) in &sections {
        system.push_str("\n\n## ");
        system.push_str(title);
        system.push('\n');
        system.push_str(body);
    }

    Composition {
        tokens: estimate_text_tokens(&system),
        system,
        memory_injected,
        memory_dropped,
    }
}

fn memory_section(memories: &[MemoryEntry], today: Date) -> (String, usize, usize) {
    let mut ordered: Vec<&MemoryEntry> = memories
        .iter()
        .filter(|entry| !entry.is_expired(today))
        .collect();
    ordered.sort_by_key(|entry| (entry.is_stale(today), std::cmp::Reverse(entry.confirmed)));

    let mut lines = String::new();
    let mut used = 0usize;
    let mut injected = 0usize;
    for entry in &ordered {
        let mut line = format!(
            "- [m-{} · {} · {}] {}",
            entry.id,
            if entry.tags.is_empty() {
                "general".to_string()
            } else {
                entry.tags.join(", ")
            },
            entry.confirmed,
            entry.text
        );
        if entry.is_stale(today) {
            line.push_str(&format!("（未验证，自 {} 起）", entry.confirmed));
        }
        let cost = estimate_text_tokens(&line) + 1;
        if used + cost > MEMORY_BUDGET {
            continue;
        }
        used += cost;
        injected += 1;
        lines.push_str(&line);
        lines.push('\n');
    }

    let dropped = memories.len().saturating_sub(injected);
    (lines.trim_end().to_string(), injected, dropped)
}

fn loop_section(loops: &[LoopItem], today: Date) -> String {
    let mut open: Vec<&LoopItem> = loops.iter().filter(|item| !item.done).collect();
    open.sort_by_key(|item| (item.due.is_none(), item.due, item.is_overdue(today)));

    let mut lines = String::new();
    let mut used = 0usize;
    for item in open {
        let mut line = format!("- [ ] l-{} {}", item.id, item.text);
        if let Some(due) = item.due {
            if item.is_overdue(today) {
                line.push_str(&format!("（截止 {due}，已逾期）"));
            } else {
                line.push_str(&format!("（截止 {due}）"));
            }
        }
        let cost = estimate_text_tokens(&line) + 1;
        if used + cost > LOOP_BUDGET {
            break;
        }
        used += cost;
        lines.push_str(&line);
        lines.push('\n');
    }
    lines.trim_end().to_string()
}

fn journal_section(journal: &[JournalDay]) -> String {
    let mut chosen: Vec<&JournalDay> = Vec::new();
    let mut used = 0usize;
    for day in journal {
        let mut block = format!("### {}\n", day.date);
        for bullet in &day.bullets {
            block.push_str(&format!("- {bullet}\n"));
        }
        let cost = estimate_text_tokens(&block) + 1;
        if used + cost > JOURNAL_BUDGET {
            break;
        }

//! In-band protocol blocks.
//!
//! The model may end an answer with `<<niuse:memory>>`, `<<niuse:loop>>`, or
//! `<<niuse:journal>>` blocks. They are stripped before rendering and turned
//! into durable records. No second model call is involved.

use crate::date::Date;
use crate::model::{one_line, MemoryKind};

pub const MARKER: &str = "<<niuse:";
const CLOSE_PREFIX: &str = "<</niuse:";

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Block {
    Memory {
        kind: MemoryKind,
        tags: Vec<String>,
        text: String,
    },
    Loop {
        due: Option<Date>,
        text: String,
    },
    Journal {
        bullets: Vec<String>,
    },
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Parsed {
    pub visible: String,
    pub blocks: Vec<Block>,
}

/// Parse every complete block, returning the text the user should see.
pub fn parse(text: &str) -> Parsed {
    let mut visible = String::new();
    let mut blocks = Vec::new();
    let mut rest = text;

    loop {
        let Some(start) = rest.find(MARKER) else {
            visible.push_str(rest);
            break;
        };
        visible.push_str(&rest[..start]);
        let candidate = &rest[start..];
        let complete = candidate.find(">>").and_then(|header_end| {
            let body_start = header_end + 2;
            let close_rel = candidate[body_start..].find(CLOSE_PREFIX)?;
            let close_start = body_start + close_rel;
            let close_end = candidate[close_start..].find(">>")? + close_start + 2;
            Some((header_end, body_start, close_start, close_end))
        });

        let Some((header_end, body_start, close_start, close_end)) = complete else {
            // An unterminated block is model output, not a protocol message:
            // show it rather than silently eating the answer.
            visible.push_str(candidate);
            break;
        };

        if let Some(block) = parse_block(
            &candidate[..header_end + 2],
            &candidate[body_start..close_start],
        ) {
            blocks.push(block);
        }
        rest = &candidate[close_end..];
    }

    Parsed {
        visible: visible.trim_end().to_string(),
        blocks,
    }
}

fn parse_block(header: &str, body: &str) -> Option<Block> {
    let inner = header.strip_prefix(MARKER)?.strip_suffix(">>")?;
    let mut parts = inner.split_whitespace();
    let name = parts.next()?;
    let mut attributes = std::collections::HashMap::new();
    for part in parts {
        if let Some((key, value)) = part.split_once('=') {
            attributes.insert(key, value);
        }
    }

    match name {
        "memory" => {
            let kind = attributes
                .get("kind")
                .and_then(|value| MemoryKind::parse(value))
                .unwrap_or(MemoryKind::Preference);
            let tags = attributes
                .get("tags")
                .map(|value| {
                    value
                        .split(',')
                        .map(str::trim)
                        .filter(|tag| !tag.is_empty())
                        .map(str::to_string)
                        .collect()
                })
                .unwrap_or_default();
            let text = one_line(body.to_string());
            (!text.is_empty()).then_some(Block::Memory { kind, tags, text })
        }
        "loop" => {
            let text = one_line(body.to_string());
            let due = attributes.get("due").and_then(|value| Date::parse(value));
            (!text.is_empty()).then_some(Block::Loop { due, text })
        }
        "journal" => {
            let bullets: Vec<String> = body
                .lines()
                .map(|line| one_line(line.trim_start_matches(['-', '*']).to_string()))
                .filter(|line| !line.is_empty())
                .take(5)
                .collect();
            (!bullets.is_empty()).then_some(Block::Journal { bullets })
        }
        _ => None,
    }
}

/// Streaming view of the model output.
///
/// Text is released as soon as it cannot be the prefix of a protocol block.
/// Complete blocks are swallowed; `finish` returns the full raw text so the
/// caller can parse the blocks without having kept a second buffer.
#[derive(Debug, Default)]
pub struct StreamFilter {
    buffer: String,
    raw: String,
}

impl StreamFilter {
    pub fn new() -> Self {
        Self::default()
    }

    /// Feed one delta, returning visible text that is safe to print now.
    pub fn push(&mut self, delta: &str) -> String {
        self.buffer.push_str(delta);
        self.raw.push_str(delta);

        let mut visible = String::new();
        loop {
            if let Some(start) = self.buffer.find(MARKER) {
                if start > 0 {
                    visible.push_str(&self.buffer[..start]);
                    self.buffer.drain(..start);
                }
                let Some(header_end) = self.buffer.find(">>") else {
                    break;
                };
                let body_start = header_end + 2;
                let Some(close_rel) = self.buffer[body_start..].find(CLOSE_PREFIX) else {
                    break;
                };
                let close_start = body_start + close_rel;
                let Some(close_tail) = self.buffer[close_start..].find(">>") else {
                    break;
                };
                let close_end = close_start + close_tail + 2;
                self.buffer.drain(..close_end);
                continue;
            }

            let hold = held_suffix_len(&self.buffer);
            let flush = self.buffer.len() - hold;
            visible.push_str(&self.buffer[..flush]);
            self.buffer.drain(..flush);
            break;
        }
        visible
    }

    /// Flush the held tail and return `(tail, raw_text)`.
    pub fn finish(&mut self) -> (String, String) {
        let tail = std::mem::take(&mut self.buffer);
        let raw = std::mem::take(&mut self.raw);
        (tail, raw)
    }
}

/// How many trailing bytes could still grow into `<<niuse:`.
fn held_suffix_len(buffer: &str) -> usize {
    let max = MARKER.len().min(buffer.len());
    for length in (1..=max).rev() {
        let start = buffer.len() - length;
        if buffer.is_char_boundary(start) && MARKER.starts_with(&buffer[start..]) {
            return length;
        }
    }
    0
}

#[cfg(test)]

//! Write-time policy: secret scanning and near-duplicate detection.
//!
//! Both are deliberately conservative. A false positive costs one `[f]orce`
//! keystroke; a false negative puts a credential in every future request.

use std::collections::HashSet;
use std::sync::OnceLock;

use regex::Regex;

/// Similarity at which two entries are treated as the same claim.
pub const TEXT_THRESHOLD: f64 = 0.5;
/// Lower bar when the entries share a tag: short entries rarely reach 0.5.
pub const TAG_THRESHOLD: f64 = 0.35;

/// Returns a human-readable reason when `text` looks like it carries a
/// credential. This is a backstop, not a guarantee.
pub fn secret_reason(text: &str) -> Option<&'static str> {
    patterns()
        .iter()
        .find(|(pattern, _)| pattern.is_match(text))
        .map(|(_, reason)| *reason)
}

fn patterns() -> &'static [(Regex, &'static str)] {
    static PATTERNS: OnceLock<Vec<(Regex, &'static str)>> = OnceLock::new();
    PATTERNS.get_or_init(|| {
        let pattern = |source: &str| Regex::new(source).expect("valid built-in regex");
        vec![
            (pattern(r"sk-[A-Za-z0-9_-]{16,}"), "API key (sk-)"),
            (pattern(r"ghp_[A-Za-z0-9]{20,}"), "GitHub token (ghp_)"),
            (
                pattern(r"github_pat_[A-Za-z0-9_]{20,}"),
                "GitHub token (github_pat_)",
            ),
            (pattern(r"AKIA[0-9A-Z]{16}"), "AWS access key (AKIA)"),
            (
                pattern(r"-----BEGIN [A-Z ]*PRIVATE KEY-----"),
                "private key block",
            ),
            (
                pattern(r"xox[baprs]-[A-Za-z0-9-]{10,}"),
                "Slack token (xox)",
            ),
            (pattern(r"AIza[0-9A-Za-z_-]{20,}"), "Google API key (AIza)"),
            (
                pattern(r"\b[0-9a-fA-F]{32,}\b"),
                "long hex string (possible key or digest)",
            ),
        ]
    })
}

/// Character-bigram Jaccard similarity. Works for Chinese and English without
/// a tokenizer, and is cheap enough to run over a few hundred entries.
pub fn similarity(left: &str, right: &str) -> f64 {
    let left_normalized = normalized_chars(left);
    let right_normalized = normalized_chars(right);
    if left_normalized.is_empty() || right_normalized.is_empty() {
        return f64::from(left_normalized == right_normalized);
    }

    let left_shingles = shingles(&left_normalized);
    let right_shingles = shingles(&right_normalized);
    let intersection = left_shingles.intersection(&right_shingles).count() as f64;
    let union = left_shingles.union(&right_shingles).count() as f64;
    if union == 0.0 {
        return 0.0;
    }
    intersection / union
}

pub fn conflicts(
    left_text: &str,
    left_tags: &[String],
    right_text: &str,
    right_tags: &[String],
) -> bool {
    let score = similarity(left_text, right_text);
    if score >= TEXT_THRESHOLD {
        return true;
    }
    let shared = left_tags
        .iter()
        .any(|tag| right_tags.iter().any(|other| other == tag));
    shared && score >= TAG_THRESHOLD
}

fn normalized_chars(input: &str) -> Vec<char> {
    input
        .chars()
        .flat_map(char::to_lowercase)
        .filter(|character| character.is_alphanumeric())
        .collect()
}

fn shingles(chars: &[char]) -> HashSet<(char, char)> {
    chars
        .windows(2)
        .map(|window| (window[0], window[1]))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn detects_common_key_shapes() {
        assert!(secret_reason("token sk-abcdefghijklmnopqrstuvwxyz").is_some());
        assert!(secret_reason("ghp_abcdefghijklmnopqrstuvwx").is_some());
        assert!(secret_reason("AKIAABCDEFGHIJKLMNOP").is_some());
        assert!(secret_reason("-----BEGIN RSA PRIVATE KEY-----").is_some());
        assert!(secret_reason("xoxb-1234567890-abcdef").is_some());
        assert!(secret_reason("0123456789abcdef0123456789abcdef").is_some());
    }

    #[test]
    fn ordinary_prose_is_not_flagged() {
        assert!(secret_reason("Rust 仓库一律用 cargo nextest").is_none());
        assert!(secret_reason("commit deadbeef").is_none());
        assert!(secret_reason("sk-短").is_none());
    }

    #[test]
    fn identical_claims_are_conflicts() {
        assert!(conflicts("用 nextest", &[], "用 nextest", &[]));
    }

    #[test]
    fn similar_claims_are_conflicts() {
        let left = "Rust 仓库一律使用 cargo nextest，不要用 cargo test";
        let right = "Rust 仓库一律用 cargo nextest，不用 cargo test";
        assert!(similarity(left, right) >= TEXT_THRESHOLD);
    }

    #[test]
    fn unrelated_claims_are_not_conflicts() {
        assert!(!conflicts("用 nextest 跑测试", &[], "先给结论再展开", &[]));
    }

    #[test]
    fn shared_tag_lowers_the_bar() {
        let tags = vec!["rust".to_string()];
        assert!(conflicts(
            "Rust 项目用 nextest",
            &tags,
            "Rust 项目不要用 nextest",
            &tags
        ));
    }
}

//! Session glue between niuse's stores and niucode's turn loop.

use std::fs;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result};
use niucode_agent::{
    project_history, run_with_history, AgentConfig, AgentEvent, ApprovalMode, ApprovalRequest,
    RunOutcome,
};
use niucode_core::{load, now_ms, Event, SessionLog};
use niucode_provider::{ChatMessage, Provider};
use niucode_tools::SandboxPolicy;

use crate::render::{approve, Renderer};

pub struct SessionMeta<'a> {
    pub cwd: &'a Path,
    pub model: &'a str,
    pub provider: &'a str,
    pub policy: SandboxPolicy,
    pub approval: ApprovalMode,
}

pub struct Thread {
    pub log: SessionLog,
    pub path: PathBuf,
}

/// Open the durable thread, creating it on first use.
pub fn open_thread(path: &Path, meta: &SessionMeta<'_>) -> Result<Thread> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)
            .with_context(|| format!("create directory {}", parent.display()))?;
    }
    let created = !path.exists() || fs::metadata(path).map(|m| m.len() == 0).unwrap_or(true);
    if !path.exists() {
        fs::File::create(path).with_context(|| format!("create thread {}", path.display()))?;
        set_private(path)?;
    }

    let log = SessionLog::open(path)?;
    if created {
        append_start(&log, meta)?;
    }
    Ok(Thread {
        log,
        path: path.to_path_buf(),
    })
}

pub fn append_start(log: &SessionLog, meta: &SessionMeta<'_>) -> Result<()> {
    log.append(&Event::SessionStart {
        id: log.id().to_string(),
        cwd: meta.cwd.display().to_string(),
        model: meta.model.to_string(),
        provider: meta.provider.to_string(),
        ts: now_ms(),
    })?;
    log.append(&Event::Policy {
        sandbox: meta.policy.mode.as_str().to_string(),
        approval: meta.approval.as_str().to_string(),
        network: meta.policy.network.as_str().to_string(),
        backend: meta.policy.backend().to_string(),
        ts: now_ms(),
    })?;
    Ok(())
}

pub fn append_end(log: &SessionLog) -> Result<()> {
    log.append(&Event::SessionEnd { ts: now_ms() })
}

pub fn history(path: &Path) -> Result<Vec<ChatMessage>> {
    if !path.exists() {
        return Ok(Vec::new());
    }
    let loaded = load(path).with_context(|| format!("load session {}", path.display()))?;
    for warning in loaded.warnings {
        eprintln!("session warning: {warning}");
    }
    project_history(&loaded.events)
}

pub fn new_session(directory: &Path) -> Result<SessionLog> {
    fs::create_dir_all(directory)
        .with_context(|| format!("create directory {}", directory.display()))?;
    let log = SessionLog::create(directory)?;
    set_private(log.path())?;
    Ok(log)
}

#[allow(clippy::too_many_arguments)]
pub fn agent_config(
    provider: &str,
    model: &str,
    cwd: &Path,
    system_prompt: String,
    policy: SandboxPolicy,
    approval: ApprovalMode,
    allow_unsandboxed: bool,
    max_steps: usize,
) -> AgentConfig {
    let mut config = AgentConfig::new(model, cwd);
    config.provider = provider.to_string();
    config.system_prompt = system_prompt;
    config.sandbox = policy;
    config.approval = approval;
    config.allow_unsandboxed = allow_unsandboxed;
    config.max_steps = max_steps;
    let budget = niucode_provider::derived_context_budget(provider, model);
    if budget > 0 {
        config.context.budget_tokens = budget;
    }
    config
}

/// Run one user turn. `Ok(None)` means the user cancelled with Ctrl-C.
pub async fn run_turn(
    provider: &dyn Provider,
    log: &mut SessionLog,
    config: &AgentConfig,
    prompt: &str,
    history: Vec<ChatMessage>,
    renderer: &mut Renderer,
) -> Result<Option<RunOutcome>> {
    let mut observer = |event: AgentEvent| renderer.event(event);
    let mut approver = |request: &ApprovalRequest| approve(request);

    let future = run_with_history(
        provider,
        log,
        config,
        prompt,
        history,
        &mut approver,
        &mut observer,
    );
    tokio::pin!(future);

    tokio::select! {
        result = &mut future => result.map(Some),
        _ = tokio::signal::ctrl_c() => Ok(None),
    }
}

#[cfg(unix)]
fn set_private(path: &Path) -> Result<()> {
    use std::os::unix::fs::PermissionsExt;
    let mut permissions = fs::metadata(path)?.permissions();
    permissions.set_mode(0o600);
    fs::set_permissions(path, permissions)?;
    Ok(())
}

#[cfg(not(unix))]
fn set_private(_path: &Path) -> Result<()> {
    Ok(())
}

//! Cold start: read old niucode sessions, extract durable candidates with one
//! cheap model call per session, and queue them for review.
//!
//! Tool output is deliberately dropped before extraction: the value is in what
//! was said and decided, not in the file contents the agent already read.

use std::cmp::Reverse;
use std::env;
use std::io::{self, Write};
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime};

use anyhow::{Context, Result};
use futures_util::StreamExt;
use niucode_core::{load, Event};
use niucode_provider::{ChatMessage, CompletionRequest, Provider, StreamEvent};
use niuse_core::model::{normalize_tags, one_line};
use niuse_core::policy::{conflicts, secret_reason};
use niuse_core::{Date, MemoryEntry, MemoryKind, Store};
use serde::Deserialize;

const EXTRACTION_SYSTEM: &str = "你是记忆抽取器。下面是一段 coding agent 与用户的真实历史对话。\n\
只抽取三类跨会话仍然有用的信息：用户的偏好、做过的决策、踩过的坑。\n\
每条必须同时满足：脱离这段对话也能看懂；在仓库里 grep 不出来；一句话说得清。\n\
不要抽取：代码事实、文件路径、环境配置、临时任务进度、别人的信息、任何密钥。\n\
输出 JSON 数组，元素形如 {\"kind\":\"preference|lesson\",\"text\":\"...\",\"tags\":[\"...\"]}。\n\
没有值得记的就输出 []。不要输出 JSON 以外的任何文字。";

const MAX_MESSAGE_CHARS: usize = 2_000;
const MAX_TRANSCRIPT_CHARS: usize = 12_000;

#[derive(Debug, Deserialize)]
struct Candidate {
    kind: String,
    text: String,
    #[serde(default)]
    tags: Vec<String>,
}

#[derive(Debug, Clone)]
struct Pending {
    kind: MemoryKind,
    tags: Vec<String>,
    text: String,
    source: String,
}

pub async fn run(
    store: &Store,
    provider: &dyn Provider,
    model: &str,
    limit: usize,
    since_days: i64,
) -> Result<()> {
    let candidates = recent_sessions(usize::MAX, since_days)?;
    if candidates.is_empty() {
        println!("没有找到最近 {since_days} 天内的 niucode session。");
        return Ok(());
    }

    // An empty or tool-only session is not worth a model call. Fill the budget
    // with sessions that actually contain user or assistant prose.
    let mut sessions: Vec<(PathBuf, String)> = Vec::new();
    for path in candidates {
        if let Some(transcript) = transcript(&path)? {
            sessions.push((path, transcript));
            if sessions.len() >= limit {
                break;
            }
        }
    }
    if sessions.is_empty() {
        println!("最近 {since_days} 天内的 session 都没有可抽取的对话。");
        return Ok(());
    }
    println!(
        "扫描 {} 个 session（最近 {} 天，上限 {}）。",
        sessions.len(),
        since_days,
        limit
    );

    let mut raw: Vec<Pending> = Vec::new();
    for (index, (path, transcript)) in sessions.iter().enumerate() {
        eprint!("\r[{}/{}] 抽取中…", index + 1, sessions.len());
        let _ = io::stderr().flush();

        match extract(provider, model, transcript).await {
            Ok(candidates) => {
                let source = path
                    .file_stem()
                    .and_then(|stem| stem.to_str())
                    .unwrap_or("session")
                    .to_string();
                for candidate in candidates {
                    let kind = MemoryKind::parse(&candidate.kind).unwrap_or(MemoryKind::Preference);
                    let text = one_line(candidate.text);
                    if text.is_empty() {
                        continue;
                    }
                    raw.push(Pending {
                        kind,
                        tags: normalize_tags(candidate.tags),
                        text,
                        source: source.clone(),
                    });
                }
            }
            Err(error) => {
                eprintln!(
                    "\n  skip {}: {error:#}",
                    path.file_name().unwrap_or_default().to_string_lossy()
                );
            }
        }
    }
    eprintln!();

    let existing = store.memories()?;
    let mut kept: Vec<Pending> = Vec::new();
    for pending in raw {
        if secret_reason(&pending.text).is_some() {
            continue;
        }
        if existing
            .iter()
            .any(|entry| conflicts(&entry.text, &entry.tags, &pending.text, &pending.tags))
        {
            continue;
        }
        if kept
            .iter()
            .any(|other| conflicts(&other.text, &other.tags, &pending.text, &pending.tags))
        {
            continue;
        }
        kept.push(pending);
    }

    write_inbox(store, &kept)?;
    println!("{} 条候选写入 {}", kept.len(), store.inbox_path().display());
    if !kept.is_empty() {
        println!("运行 `niuse review` 逐条确认。");
    }
    Ok(())
}

pub fn review(store: &Store) -> Result<()> {
    let Some(text) = store.read_inbox()? else {
        println!("没有待审队列。先运行 `niuse bootstrap`。");
        return Ok(());
    };
    let items = parse_inbox(&text);
    if items.is_empty() {
        println!("待审队列是空的。");
        return Ok(());
    }

    println!("{} 条待审。", items.len());
    let mut remaining: Vec<Pending> = Vec::new();
    let mut accepted = 0usize;
    let mut index = 0usize;

    while index < items.len() {
        let item = &items[index];
        println!();
        println!(
            "{} [{}] {}",
            item.kind.as_str(),
            if item.tags.is_empty() {
                "general".to_string()
            } else {
                item.tags.join(", ")
            },
            item.text
        );
        println!("  来源 {}", item.source);
        print!("[y] 接受  [n] 丢弃  [s] 留到下次  [q] 退出 > ");
        let _ = io::stdout().flush();

        let mut line = String::new();
        if io::stdin().read_line(&mut line)? == 0 {
            remaining.extend(items[index..].iter().cloned());
